import {$,esc,icon,common,modal,toast,load,save} from './prototype-shared.js?v=7561e6f428411d29';
import {getDocument,updateDocument} from './document-store.js?v=7561e6f428411d29';
import {personalFields,preferenceFields,militaryFields,hopeFields,sections,blankEntry,initialResume} from './resume-schema.js?v=7561e6f428411d29';
import '../custom-controls.js?v=7561e6f428411d29';
common();
const params=new URLSearchParams(location.search);
const documentId=params.get('document')||crypto.randomUUID();
if(!params.has('document'))history.replaceState(null,'','?document='+encodeURIComponent(documentId));
const linkedDocument=getDocument(documentId),storageKey='resume:'+documentId;
const state=load(storageKey,initialResume(linkedDocument));
const fieldId=(scope,key,uid='')=>'resume-'+scope+'-'+(uid?uid+'-':'')+key;
function field(f,value,scope,uid=''){
 const id=fieldId(scope,f.key,uid),attrs=`id="${id}" data-field="${f.key}" data-scope="${scope}" ${uid?`data-entry="${uid}"`:''} aria-label="${esc(f.label)}" ${f.required?'required':''}`;
 const [year,month]=String(value||'').split('-'),thisYear=new Date().getFullYear();
 const years=Array.from({length:thisYear-1950+11},(_,i)=>String(thisYear+10-i));if(year&&!years.includes(year))years.push(year);
 const input=f.type==='month'?`<div class="resume-month-control" role="group" aria-label="${esc(f.label)}"><input ${attrs} type="hidden" value="${esc(value||'')}"><select id="${id}-year" data-month-part="year" aria-label="${esc(f.label)} 연도"><option value="">연도</option>${years.map(y=>`<option value="${y}" ${y===year?'selected':''}>${y}년</option>`).join('')}</select><select data-month-part="month" aria-label="${esc(f.label)} 월"><option value="">월</option>${Array.from({length:12},(_,i)=>{const m=String(i+1).padStart(2,'0');return `<option value="${m}" ${m===month?'selected':''}>${i+1}월</option>`}).join('')}</select></div>`:f.type==='select'?`<select ${attrs}><option value="">선택해 주세요</option>${f.options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select>`:f.type==='textarea'?`<textarea ${attrs} rows="5" placeholder="내용을 입력해 주세요.">${esc(value||'')}</textarea>`:f.type==='file'?`<input ${attrs} type="file" accept=".pdf,.doc,.docx,.ppt,.pptx,.jpg,.png"><span class="resume-file-name">${value?esc(value):''}</span>`:`<input ${attrs} type="${f.type||'text'}" value="${esc(value||'')}" autocomplete="off">`;
 return `<div class="resume-field ${f.wide?'wide':''}" ${f.condition?`data-condition="${f.condition}"`:''}><label for="${id}${f.type==='month'?'-year':''}">${esc(f.label)}${f.required?'<span aria-hidden="true"> *</span>':''}</label>${input}</div>`;
}
const fields=(definitions,data,scope,uid='')=>definitions.map(f=>field(f,data[f.key],scope,uid)).join('');
function stash(){save(storageKey,state);$('#resume-save-state').textContent='변경사항 있음';}
function photo(){const host=$('#resume-photo-preview');host.innerHTML=state.photo?`<img src="${esc(state.photo)}" alt="이력서 사진">`:icon('UserRound');$('#remove-photo').hidden=!state.photo;}
function conditions(){document.querySelectorAll('[data-condition]').forEach(wrapper=>{const c=wrapper.dataset.condition;wrapper.hidden=c==='military'?state.personal.military!=='군필':c==='exemption'?state.personal.military!=='면제':!state.personal[c]||state.personal[c]==='비대상';});}
function entryHTML(section,entry,index){return `<div class="resume-entry" data-resume-entry="${entry.uid}"><header class="resume-entry-heading"><h3>${section.label} ${index+1}</h3><div>${!section.single?`<button type="button" data-entry-action="up" data-section="${section.id}" data-uid="${entry.uid}" aria-label="${section.label} ${index+1} 위로" ${index===0?'disabled':''}>${icon('ArrowUp')}</button><button type="button" data-entry-action="down" data-section="${section.id}" data-uid="${entry.uid}" aria-label="${section.label} ${index+1} 아래로" ${index===state.entries[section.id].length-1?'disabled':''}>${icon('ArrowDown')}</button>`:''}<button type="button" data-entry-action="remove" data-section="${section.id}" data-uid="${entry.uid}" aria-label="${section.label} ${index+1} 삭제" ${section.required&&state.entries[section.id].length===1?'disabled':''}>${icon('Trash2')}</button></div></header><div class="resume-fields">${fields(section.fields,entry,section.id,entry.uid)}</div></div>`;}
function renderSections(){
 $('#resume-sections').innerHTML=state.order.map(id=>{const s=sections.find(s=>s.id===id);return `<section class="resume-section" id="section-${id}" aria-labelledby="heading-${id}"><header><h2 id="heading-${id}">${s.label}</h2>${s.required?'<span class="resume-required">필수</span>':''}</header>${state.entries[id].map((entry,i)=>entryHTML(s,entry,i)).join('')}${!s.single?`<button class="btn resume-add-entry" type="button" data-add-entry="${id}">${icon('Plus')} ${s.label} 추가</button>`:''}</section>`;}).join('');
 $('#resume-nav').innerHTML=`<a href="#section-personal">기본인적사항</a>`+state.order.map(id=>{const s=sections.find(s=>s.id===id);return `<a href="#section-${id}">${s.label}<span>${state.entries[id].length}</span></a>`;}).join('');
 $('#resume-picker').innerHTML=sections.filter(s=>!s.required).map(s=>`<button type="button" class="btn" data-add-section="${s.id}" ${state.order.includes(s.id)?'disabled':''}>${icon(state.order.includes(s.id)?'Check':'Plus')}${s.label}</button>`).join('');
}
$('#resume-title').value=state.title;
$('#personal-fields').innerHTML=fields(personalFields,state.personal,'personal');
$('#preference-fields').innerHTML=fields(preferenceFields,state.personal,'personal');
$('#military-fields').innerHTML=fields(militaryFields,state.personal,'personal');
$('#resume-hope-fields').innerHTML=fields(hopeFields,state.hope,'hope');
photo();conditions();renderSections();
function focusEntry(uid){requestAnimationFrame(()=>{const e=document.querySelector(`[data-resume-entry="${uid}"]`);e?.scrollIntoView({block:'start',behavior:'smooth'});e?.querySelector('.custom-trigger,input:not([hidden]),textarea')?.focus({preventScroll:true});});}
function clearError(wrapper){wrapper?.querySelector('.resume-error')?.remove();wrapper?.querySelectorAll('[aria-invalid]').forEach(e=>{if(!e.validity?.customError)e.removeAttribute('aria-invalid');});}
function edit(event){const input=event.target;if(input.dataset.monthPart){const group=input.closest('.resume-month-control'),year=group.querySelector('[data-month-part=year]').value,month=group.querySelector('[data-month-part=month]').value,hidden=group.querySelector('input');hidden.value=year&&month?year+'-'+month:'';hidden.dispatchEvent(new Event('change',{bubbles:true}));return;}if(input.id==='resume-title'){state.title=input.value;clearError(input.parentElement);stash();return;}if(!input.dataset.field)return;const {scope,field,entry}=input.dataset;const data=scope==='personal'?state.personal:scope==='hope'?state.hope:state.entries[scope]?.find(x=>x.uid===entry);if(!data)return;data[field]=input.type==='file'?input.files[0]?.name||'':input.value;clearError(input.closest('.resume-field'));conditions();stash();}
$('#resume-form').addEventListener('input',edit);$('#resume-form').addEventListener('change',edit);
$('#resume-form').addEventListener('click',event=>{
 const button=event.target.closest('button');if(!button)return;
 if(button.dataset.addSection){const id=button.dataset.addSection,entry=blankEntry();state.entries[id]=[entry];state.order.push(id);renderSections();stash();focusEntry(entry.uid);}
 if(button.dataset.addEntry){const id=button.dataset.addEntry,entry=blankEntry();state.entries[id].push(entry);renderSections();stash();focusEntry(entry.uid);}
 if(button.dataset.entryAction){const id=button.dataset.section,uid=button.dataset.uid,list=state.entries[id],index=list.findIndex(e=>e.uid===uid),action=button.dataset.entryAction;
  if(action==='remove'){modal('항목을 삭제할까요?','<p>입력한 이 항목의 내용이 삭제됩니다.</p>',()=>{list.splice(index,1);if(!list.length){delete state.entries[id];state.order=state.order.filter(x=>x!==id);}renderSections();stash();requestAnimationFrame(()=>{const next=document.querySelector(`#section-${id} .resume-add-entry`)||document.querySelector(`[data-add-section="${id}"]`);next?.focus();});});$('#dialog-confirm').textContent='삭제';}
  else{const next=index+(action==='up'?-1:1);if(next<0||next>=list.length)return;[list[index],list[next]]=[list[next],list[index]];renderSections();stash();focusEntry(uid);}
 }
});
$('#resume-photo-input').addEventListener('change',event=>{const file=event.target.files[0];if(!file)return;if(!['image/jpeg','image/png'].includes(file.type)||file.size>2*1024*1024){toast('2MB 이하 JPG 또는 PNG를 선택해 주세요.');return;}const reader=new FileReader();reader.onload=()=>{state.photo=reader.result;photo();stash();};reader.readAsDataURL(file);});
$('#remove-photo').addEventListener('click',()=>{state.photo='';photo();stash();});
function error(element,message){const wrapper=element.closest('.resume-field,.resume-title');clearError(wrapper);const hint=document.createElement('p');hint.className='resume-error';hint.setAttribute('role','alert');hint.textContent=message;wrapper.append(hint);element.setAttribute('aria-invalid','true');let focus=element.hidden||element.type==='hidden'?(element.closest('.custom-control')?.querySelector('.custom-trigger')||wrapper.querySelector('.custom-trigger')):element;focus?.setAttribute('aria-invalid','true');for(let parent=wrapper.parentElement;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;wrapper.scrollIntoView({block:'center',behavior:'smooth'});focus?.focus({preventScroll:true});return false;}
function validate(complete){if(!state.title.trim())return error($('#resume-title'),'이력서 제목을 입력해 주세요.');if(!complete)return true;for(const field of document.querySelectorAll('#resume-form [required]'))if(!field.value.trim())return error(field,'필수 항목을 입력해 주세요.');const email=document.querySelector('[data-field=email]');if(email.value&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value))return error(email,'이메일 형식을 확인해 주세요.');for(const group of document.querySelectorAll('.resume-month-control')){const year=group.querySelector('[data-month-part=year]'),month=group.querySelector('[data-month-part=month]');if(Boolean(year.value)!==Boolean(month.value))return error(year.value?month:year,'연도와 월을 모두 선택해 주세요.');}const dateError=document.querySelector('.custom-date input[aria-invalid=true]');if(dateError)return error(dateError,'날짜 형식을 확인해 주세요.');for(const id of state.order)for(const entry of state.entries[id])if(entry.start&&entry.end&&entry.end<entry.start)return error(document.querySelector(`[data-entry="${entry.uid}"][data-field=end]`),'종료일은 시작일 이후로 입력해 주세요.');return true;}
function store(complete=false){if(!validate(complete))return;if(!save(storageKey,state))return;updateDocument(documentId,{kind:'resume',title:state.title,...state.hope,date:new Intl.DateTimeFormat('sv-SE').format(new Date()).replaceAll('-','.'),state:complete?'저장완료':'임시저장',representative:linkedDocument?.representative||false});$('#resume-save-state').textContent=complete?'저장완료':'임시저장됨';toast('이력서를 저장했습니다.');}
$('#resume-draft').addEventListener('click',()=>store(false));$('#resume-form').addEventListener('submit',event=>{event.preventDefault();store(true);});
function previewFields(definitions,data){return `<dl class="resume-preview-fields">${definitions.filter(f=>data[f.key]).map(f=>`<div><dt>${esc(f.label)}</dt><dd>${esc(data[f.key])}</dd></div>`).join('')}</dl>`;}
$('#resume-preview').addEventListener('click',()=>{modal('이력서 미리보기',`<div class="resume-preview"><h3>${esc(state.title||'제목 없음')}</h3><h4>기본인적사항</h4>${previewFields(personalFields,state.personal)}<h4>사회형평적 인재 우대사항</h4>${previewFields(preferenceFields,state.personal)}<h4>병역사항</h4>${previewFields(militaryFields,state.personal)}<h4>지원분야</h4>${previewFields(hopeFields,state.hope)}${state.order.map(id=>{const s=sections.find(s=>s.id===id);return `<h4>${s.label}</h4>${state.entries[id].map(e=>previewFields(s.fields,e)).join('')}`;}).join('')}</div>`);});
$('#resume-nav').addEventListener('click',event=>{const link=event.target.closest('a');if(!link)return;$('#resume-nav').querySelectorAll('a').forEach(a=>a.removeAttribute('aria-current'));link.setAttribute('aria-current','location');});
